"use client";

import { useState, useEffect } from "react";
import { useRouter } from "next/navigation";
import { ArrowLeft, Trophy } from "lucide-react";
import { useAuth } from "@/lib/AuthContext";
import ProtectedRoute from "@/components/ProtectedRoute";

type Question = {
  id: number;
  image?: string;
  question: string;
  options: string[];
  correct: string;
};

// CHANGE THIS FOR EACH QUIZ:
const CATEGORY_SLUG = "road-signs"; // or "dashboard" or "car-knowledge"
const CATEGORY_NAME = "Road Signs"; // or "Dashboard" or "Car Knowledge"

function QuizContent() {
  const router = useRouter();
  const { token } = useAuth();
  
  const [questions, setQuestions] = useState<Question[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  
  const [readyPhase, setReadyPhase] = useState(true);
  const [countdown, setCountdown] = useState(3);
  const [started, setStarted] = useState(false);
  const [current, setCurrent] = useState(0);
  const [selected, setSelected] = useState<string | null>(null);
  const [score, setScore] = useState(0);
  const [showResult, setShowResult] = useState(false);
  const [timeLeft, setTimeLeft] = useState(60);
  const [timeUp, setTimeUp] = useState(false);
  const [quizStartTime, setQuizStartTime] = useState<number>(0);

  // Fetch questions from backend
  useEffect(() => {
    async function fetchQuestions() {
      try {
        const response = await fetch(`http://localhost:5000/api/questions/${CATEGORY_SLUG}`, {
          headers: {
            'Authorization': `Bearer ${token}`
          }
        });

        if (!response.ok) {
          throw new Error('Failed to fetch questions');
        }

        const data = await response.json();
        setQuestions(data);
        setLoading(false);
      } catch (err: any) {
        setError(err.message || 'Failed to load questions');
        setLoading(false);
      }
    }

    if (token) {
      fetchQuestions();
    }
  }, [token]);

  // Countdown logic
  useEffect(() => {
    if (readyPhase) {
      const readyTimeout = setTimeout(() => {
        setReadyPhase(false);
      }, 1500);
      return () => clearTimeout(readyTimeout);
    } else if (!started && countdown > 0) {
      const timer = setInterval(() => {
        setCountdown((prev) => {
          if (prev <= 1) {
            clearInterval(timer);
            setStarted(true);
            setQuizStartTime(Date.now());
          }
          return prev - 1;
        });
      }, 1000);
      return () => clearInterval(timer);
    }
  }, [readyPhase, countdown, started]);

  // Quiz timer
  useEffect(() => {
    if (!started || showResult) return;
    if (timeLeft <= 0) {
      setTimeUp(true);
      saveResult();
      return;
    }
    const timer = setInterval(() => setTimeLeft((t) => t - 1), 1000);
    return () => clearInterval(timer);
  }, [started, showResult, timeLeft]);

  // Save result to backend
  const saveResult = async () => {
    const timeTaken = Math.floor((Date.now() - quizStartTime) / 1000);
    
    try {
      await fetch('http://localhost:5000/api/results', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${token}`
        },
        body: JSON.stringify({
          category: CATEGORY_SLUG,
          score,
          totalQuestions: questions.length,
          timeTaken
        })
      });
    } catch (err) {
      console.error('Failed to save result:', err);
    }
  };

  const handleAnswer = (option: string) => {
    setSelected(option);
    const isCorrect = option === question.correct;
    if (isCorrect) {
      setScore((prev) => prev + 1);
    }
    
    setTimeout(() => {
      if (current + 1 < questions.length) {
        setCurrent(current + 1);
        setSelected(null);
      } else {
        setShowResult(true);
        saveResult();
      }
    }, 800);
  };

  const restartQuiz = () => {
    setCurrent(0);
    setSelected(null);
    setScore(0);
    setShowResult(false);
    setTimeLeft(60);
    setTimeUp(false);
    setStarted(false);
    setCountdown(3);
    setReadyPhase(true);
  };

  // Loading state
  if (loading) {
    return (
      <main className="min-h-screen bg-black text-white flex items-center justify-center">
        <div className="text-center">
          <div className="w-16 h-16 border-4 border-[#c8a951] border-t-transparent rounded-full animate-spin mx-auto mb-4"></div>
          <p className="text-[#c8a951] text-lg">Loading questions...</p>
        </div>
      </main>
    );
  }

  // Error state
  if (error) {
    return (
      <main className="min-h-screen bg-black text-white flex items-center justify-center p-6">
        <div className="text-center max-w-md">
          <div className="text-red-400 text-6xl mb-4">⚠️</div>
          <h2 className="text-2xl font-bold text-red-400 mb-4">Error Loading Quiz</h2>
          <p className="text-gray-400 mb-6">{error}</p>
          <button
            onClick={() => router.push('/game')}
            className="px-6 py-3 bg-[#c8a951] text-black rounded-xl font-bold hover:bg-[#d9b85c] transition-all"
          >
            Back to Menu
          </button>
        </div>
      </main>
    );
  }

  if (questions.length === 0) {
    return (
      <main className="min-h-screen bg-black text-white flex items-center justify-center">
        <div className="text-center">
          <p className="text-[#c8a951] text-lg">No questions available for this category</p>
          <button
            onClick={() => router.push('/game')}
            className="mt-6 px-6 py-3 bg-[#c8a951] text-black rounded-xl font-bold hover:bg-[#d9b85c] transition-all"
          >
            Back to Menu
          </button>
        </div>
      </main>
    );
  }

  const question = questions[current];
  const circleRadius = 45;
  const circumference = 2 * Math.PI * circleRadius;
  const progress = (timeLeft / 60) * circumference;

  const feedback =
    score === questions.length
      ? "Perfect! You're a master!"
      : score >= questions.length * 0.75
      ? "Excellent! You know your stuff!"
      : score >= questions.length * 0.5
      ? "Good effort! Keep practicing!"
      : "Keep learning — you'll improve!";

  return (
    <main className="min-h-screen bg-black text-white flex flex-col items-center justify-center p-6 relative overflow-hidden">
      {/* Background Effects */}
      <div className="absolute inset-0">
        <div className="absolute top-1/4 left-1/4 w-96 h-96 bg-[#c8a951]/5 rounded-full blur-3xl animate-pulse"></div>
        <div className="absolute bottom-1/4 right-1/4 w-96 h-96 bg-[#c8a951]/5 rounded-full blur-3xl animate-pulse delay-700"></div>
      </div>

      {/* Back Button */}
      <button
        onClick={() => router.push("/game")}
        className="absolute top-6 left-6 z-50 flex items-center gap-2 border-2 border-[#c8a951]/30 text-[#c8a951] px-5 py-2.5 rounded-xl hover:bg-[#c8a951] hover:text-black hover:border-[#c8a951] transition-all duration-300 font-semibold backdrop-blur-sm"
      >
        <ArrowLeft className="w-5 h-5" />
        Back
      </button>

      {/* Ready Phase */}
      {readyPhase && (
        <div className="relative z-10 text-center">
          <div className="text-8xl font-black text-[#c8a951] animate-pulse drop-shadow-[0_0_40px_rgba(200,169,81,0.6)]">
            Ready!
          </div>
        </div>
      )}

      {/* Countdown Phase */}
      {!readyPhase && !started && countdown > 0 && (
        <div className="relative z-10 text-center">
          <div className="text-9xl font-black text-[#c8a951] animate-bounce drop-shadow-[0_0_60px_rgba(200,169,81,0.8)]">
            {countdown}
          </div>
        </div>
      )}

      {/* Time Up Screen */}
      {timeUp && !showResult && (
        <div className="relative z-10 text-center bg-gradient-to-b from-[#0a0a0a] to-black border-2 border-[#c8a951]/30 rounded-3xl p-12 max-w-lg shadow-[0_0_60px_rgba(200,169,81,0.2)] backdrop-blur-sm">
          <h2 className="text-5xl font-bold mb-6 text-[#c8a951]">Time's Up!</h2>
          <p className="text-2xl mb-8 text-gray-300">
            You scored <span className="text-[#c8a951] font-bold">{score}/{questions.length}</span>
          </p>
          <button
            onClick={restartQuiz}
            className="px-8 py-4 bg-[#c8a951] text-black rounded-xl font-bold text-lg hover:bg-[#d9b85c] transition-all duration-300 hover:scale-105 shadow-[0_0_30px_rgba(200,169,81,0.4)]"
          >
            Try Again
          </button>
        </div>
      )}

      {/* Result Screen */}
      {showResult && (
        <div className="relative z-10 text-center bg-gradient-to-b from-[#0a0a0a] to-black border-2 border-[#c8a951] rounded-3xl p-12 max-w-2xl w-full shadow-[0_0_80px_rgba(200,169,81,0.3)] backdrop-blur-sm">
          <div className="flex justify-center mb-8">
            <div className="p-6 rounded-full bg-[#c8a951]/10 border-4 border-[#c8a951] animate-pulse">
              <Trophy className="w-16 h-16 text-[#c8a951]" />
            </div>
          </div>

          <h2 className="text-5xl font-black mb-6 text-[#c8a951] drop-shadow-[0_0_20px_rgba(200,169,81,0.6)]">
            {CATEGORY_NAME} Quiz Complete!
          </h2>

          <p className="text-2xl text-gray-300 mb-8 font-light">{feedback}</p>

          <div className="text-8xl font-black mb-10 text-[#c8a951] drop-shadow-[0_0_30px_rgba(200,169,81,0.8)]">
            {score}/{questions.length}
          </div>

          <div className="flex flex-col sm:flex-row justify-center gap-5">
            <button
              onClick={restartQuiz}
              className="px-8 py-4 rounded-xl bg-[#c8a951] text-black font-bold text-lg hover:bg-[#d9b85c] transition-all duration-300 hover:scale-105 shadow-[0_0_30px_rgba(200,169,81,0.4)]"
            >
              Play Again
            </button>
            <button
              onClick={() => router.push("/game")}
              className="px-8 py-4 rounded-xl border-2 border-[#c8a951] text-[#c8a951] font-bold text-lg hover:bg-[#c8a951] hover:text-black transition-all duration-300 hover:scale-105"
            >
              Back to Menu
            </button>
          </div>
        </div>
      )}

      {/* Quiz Interface */}
      {started && !showResult && !timeUp && (
        <div className="relative z-10 text-center bg-gradient-to-b from-[#0a0a0a] to-black border-2 border-[#c8a951]/30 rounded-3xl p-10 max-w-2xl w-full shadow-[0_0_60px_rgba(200,169,81,0.2)] backdrop-blur-sm">
          {/* Timer Circle */}
          <div className="flex justify-center mb-8 relative">
            <svg width="120" height="120">
              <circle cx="60" cy="60" r={circleRadius} stroke="#1a1a1a" strokeWidth="10" fill="none" />
              <circle
                cx="60"
                cy="60"
                r={circleRadius}
                stroke="#c8a951"
                strokeWidth="10"
                fill="none"
                strokeDasharray={circumference}
                strokeDashoffset={circumference - progress}
                strokeLinecap="round"
                className="transition-all duration-1000 ease-linear"
                style={{ filter: 'drop-shadow(0 0 10px rgba(200,169,81,0.6))' }}
              />
            </svg>
            <span className="absolute inset-0 flex items-center justify-center text-3xl font-bold text-[#c8a951]">
              {timeLeft}s
            </span>
          </div>

          {/* Progress */}
          <div className="mb-8">
            <div className="flex justify-between text-sm text-gray-400 mb-2">
              <span>Question {current + 1}</span>
              <span>{questions.length} Total</span>
            </div>
            <div className="w-full h-2 bg-[#1a1a1a] rounded-full overflow-hidden">
              <div 
                className="h-full bg-[#c8a951] transition-all duration-300 rounded-full"
                style={{ width: `${((current + 1) / questions.length) * 100}%` }}
              ></div>
            </div>
          </div>

          {/* Question Image (if exists) */}
          {question.image && (
            <div className="mb-8 flex justify-center">
              <div className="p-6 bg-[#1a1a1a] rounded-2xl border-2 border-[#c8a951]/20">
                <img
                  src={question.image}
                  alt="Question image"
                  className="w-48 h-48 object-contain"
                />
              </div>
            </div>
          )}

          {/* Question */}
          <h3 className="text-2xl font-bold mb-8 text-white">
            {question.question}
          </h3>

          {/* Options */}
          <div className="grid gap-4">
            {question.options.map((option) => (
              <button
                key={option}
                onClick={() => handleAnswer(option)}
                disabled={!!selected}
                className={`px-6 py-4 rounded-xl text-lg font-semibold transition-all duration-300 border-2
                ${
                  selected
                    ? option === question.correct
                      ? "border-green-500 bg-green-500/20 scale-105 text-green-400"
                      : option === selected
                      ? "border-red-500 bg-red-500/20 scale-95 text-red-400"
                      : "border-[#1a1a1a] bg-[#1a1a1a]/50 opacity-50 text-gray-500"
                    : "border-[#c8a951]/30 bg-[#1a1a1a] hover:bg-[#c8a951] hover:border-[#c8a951] hover:text-black hover:scale-105 text-white"
                }`}
              >
                {option}
              </button>
            ))}
          </div>
        </div>
      )}
    </main>
  );
}

export default function Quiz() {
  return (
    <ProtectedRoute>
      <QuizContent />
    </ProtectedRoute>
  );
}